-- catalog-override: Preserve RisingWave's native DATE_DIFF mutation predicate; SQLGlot rewrites it as epoch arithmetic.
UPDATE {table_relation} SET dm_close = dm_close + 0.01, dm_high = dm_high + 0.01, dm_vol = dm_vol + 1 WHERE abs((date_diff('day', DATE '1970-01-01', dm_date) * 2654435761 + coalesce(ascii(substr(dm_s_symb, 1, 1)), 0) * 9176 + coalesce(ascii(substr(dm_s_symb, 2, 1)), 0) + {batch_offset}) % 1000000) >= {start} AND abs((date_diff('day', DATE '1970-01-01', dm_date) * 2654435761 + coalesce(ascii(substr(dm_s_symb, 1, 1)), 0) * 9176 + coalesce(ascii(substr(dm_s_symb, 2, 1)), 0) + {batch_offset}) % 1000000) < {end};
